//! First enemy pass: a hopping blue slime, a flying demon eye and a walking zombie,
//! modelled on the simplest `NPC.cs` behaviours.

use glam::Vec2;
use tr_core::{TILE_PX, UnifiedRandom, World};

use crate::npc_ai::{HoverParams, HoverRotation};
use crate::projectile::angle_towards;
