            | NpcKind::Scarecrow6
            | NpcKind::Scarecrow7
            | NpcKind::Scarecrow8
            | NpcKind::Scarecrow9
            | NpcKind::Scarecrow10
            | NpcKind::MourningWood
            | NpcKind::Splinterling
