    #[test]
    fn eoc_bursts_servants_when_below_the_player() {
        // The hover arm's servant burst: the eye below the player within
        // 500 px counts `ai[3]` to 110 and requests the spawn.
        let mut w = ground();
        w.day_time = false;
        let mut player = Player::spawn(&w);
        for _ in 0..60 {
            player.update(&w, crate::player::PlayerInput::default());
        }
        let (pcx, pcy) = player.center();
        let mut eye = Npc::spawn_eye_of_cthulhu(&w, pcx, pcy).unwrap();
        // Re-anchor the eye below the player: the spawn put it 600 px above;
        // the burst condition reads `self.y + h < player.y` (the eye ABOVE
        // the player) — flip the positions: put the EYE high and the PLAYER
        // below by moving the eye down and the player's Y under it.
        eye.y = pcy - 300.0 - 110.0;
        eye.ai = [0.0, 0.0, 0.0, 0.0];
        for _ in 0..130 {
            eye.update(&w, &mut player, 1.0 / 60.0);
        }
        assert!(eye.wants_servant.is_some(), "the servant burst request");
        let (sx, sy, svx, svy) = eye.wants_servant.unwrap();
        assert!(svx != 0.0 || svy != 0.0, "the launch velocity");
        // The world sim resolves the request into a real servant.
        let mut servant = Npc::spawn_servant_of_cthulhu(sx, sy, svx, svy);
        assert_eq!(servant.max_hp, 8);
        assert_eq!(servant.kind, NpcKind::ServantOfCthulhu);
        servant.update(&w, &mut player, 1.0 / 60.0);
        assert!(servant.hp > 0);
    }

    /// W4-d22 (style-4 RNG census): a plain hover tick draws exactly ONE
    /// `Next(5)` (the dust gate, `NPC.cs:20062`) on the caller's stream —
    /// the gate rolls EVERY tick before the dawn-flee return. The witness
    /// replays the draw against a same-seeded twin: the axis passes the
    /// caller's stream through (the pre-W4-d22 kind-arm entry took no rng
    /// and skipped the gate, desyncing UpdateNPCs every tick).
    #[test]
    fn w4_d22_the_eoc_hover_tick_draws_the_one_dust_gate() {
        let mut w = ground_air();
        w.day_time = false;
        let mut player = surface_player(&w);
        player.x = 100.0 * TILE_PX;
        player.y = 116.0 * TILE_PX;
        let mut eye = Npc::spawn_eye_of_cthulhu(&w, player.center().0, player.center().1).unwrap();
        eye.hp = eye.max_hp;
        // Park the eye in the hover, far from the servant-burst window.
        eye.ai = [0.0, 0.0, 0.0, 0.0];
        eye.x = 80.0 * TILE_PX;
        eye.y = 40.0 * TILE_PX;
        let mut rng = UnifiedRandom::new(7);
        let mut witness = rng.clone();
        let _gate = witness.next_max(5);
        eye.update_rng(&w, &mut player, 1.0 / 60.0, &mut rng);
        assert_eq!(rng.peek(), witness.peek(), "one Next(5) gate draw, nothing else");
        assert_eq!(eye.ai[2], 1.0, "the hover counter climbed");
    }

    /// W4-d22: the dawn-flee tick STILL draws the `Next(5)` gate (the C#
    /// rolls it at `:20062` before the `:20069` day/dead return) — the
    /// climb-away does not skip the draw.
    #[test]
    fn w4_d22_the_eoc_dawn_flee_tick_still_draws_the_gate() {
        let mut w = ground_air();
        w.day_time = true; // the dawn flee
        let mut player = surface_player(&w);
        let mut eye = Npc::spawn_eye_of_cthulhu(&w, player.center().0, player.center().1).unwrap();
        eye.hp = eye.max_hp;
        let mut rng = UnifiedRandom::new(11);
        let mut witness = rng.clone();
        let _gate = witness.next_max(5);
        eye.update_rng(&w, &mut player, 1.0 / 60.0, &mut rng);
        assert_eq!(rng.peek(), witness.peek(), "the flee tick draws the gate too");
        assert!(eye.despawn_timer >= 0, "EncourageDespawn(10) armed");
    }

    fn the_witch_doctor_arrival_gate_and_shop() {
        // The arrival: the downedQueenBee gate (constants-off in the port).
        assert!(!crate::spawner::spawn_allowed_witch_doctor(false));
        assert!(crate::spawner::spawn_allowed_witch_doctor(true));
        // The shop index 16 (W4-d123, `Chest.cs:2615-2671`): the Blowgun/
        // Flask head + the ten always summon/flask rows.
        let stock = crate::shop::resolve_stock(16, &crate::shop::ShopFlags::default(), &[]);
        for id in [1430, 986, 909, 910, 940, 941, 942, 943, 944, 945, 4922, 4417] {
            assert!(stock.contains(&id), "the always row {id}");
        }
        assert!(!stock.contains(&1158), "the night row leaks");
        assert!(!stock.contains(&2999), "no Wizard-presence row");
        assert!(!stock.contains(&6147), "no jungle row off-zone");
        // The night row (`:2626`).
        let night = crate::shop::ShopFlags { night: true, ..Default::default() };
        assert!(crate::shop::resolve_stock(16, &night, &[]).contains(&1158));
        // The Wizard-presence row (`:2618`).
        let wiz = crate::shop::ShopFlags { wizard_present: true, ..Default::default() };
        assert!(crate::shop::resolve_stock(16, &wiz, &[]).contains(&2999));
        // The jungle row (`:2622`).
        let jungle = crate::shop::ShopFlags { zone_jungle: true, ..Default::default() };
        assert!(crate::shop::resolve_stock(16, &jungle, &[]).contains(&6147));
        // The hardmode+Plantera imbuing block (`:2630-2640`).
        let hp = crate::shop::ShopFlags {
            hard_mode: true, downed_plant_boss: true, ..Default::default()
        };
        let hpr = crate::shop::resolve_stock(16, &hp, &[]);
        for id in [1159, 1160, 1161, 1339] {
            assert!(hpr.contains(&id), "the imbuing row {id}");
        }
        assert!(!hpr.contains(&1167), "1167 needs the jungle conjunct");
        // Hardmode alone does NOT open the imbuing block (Plantera needed).
        let hard = crate::shop::ShopFlags { hard_mode: true, ..Default::default() };
        assert!(!crate::shop::resolve_stock(16, &hard, &[]).contains(&1159));
        // The jungle conjunct inside the block (`:2635`) opens 1167.
        let hpj = crate::shop::ShopFlags {
            hard_mode: true, downed_plant_boss: true, zone_jungle: true, ..Default::default()
        };
        assert!(crate::shop::resolve_stock(16, &hpj, &[]).contains(&1167));
        // The hardmode+jungle 1171 (`:2641`) + the night+Plantera 1162 (`:2644`).
        let hj = crate::shop::ShopFlags {
            hard_mode: true, zone_jungle: true, ..Default::default()
        };
        let hjr = crate::shop::resolve_stock(16, &hj, &[]);
        assert!(hjr.contains(&1171));
        assert!(!hjr.contains(&1162), "1162 needs night + Plantera");
        let hjnp = crate::shop::ShopFlags {
            hard_mode: true, zone_jungle: true, night: true, downed_plant_boss: true,
            ..Default::default()
        };
        assert!(crate::shop::resolve_stock(16, &hjnp, &[]).contains(&1162));
        // The carried-item restocks (`:2659-2666`).
        assert!(crate::shop::resolve_stock(16, &crate::shop::ShopFlags::default(), &[1835]).contains(&1836));
        assert!(crate::shop::resolve_stock(16, &crate::shop::ShopFlags::default(), &[1258]).contains(&1261));
    }

