    #[test]
    fn the_prime_cycles() {
        // `AI_032`'s v1 cycle: the hover 480 ticks → the charge (the
        // velocity 9) → the decel.
        let mut w = ground_air();
        w.day_time = false;
        // The aiStyle-32 head (`NPC.cs:27626-27942`): the ai[1] state
        // machine (0 hover / 1 enraged charge / 2 day-rage / 3 despawn).
        let mut pr = Npc::new(NpcKind::SkeletronPrime, 80.0 * 16.0, 20.0 * 16.0, 1, 0.0);
        pr.hp = pr.max_hp;
        let mut player = surface_player(&w);
        player.x = 100.0 * TILE_PX;
        player.y = 116.0 * TILE_PX;
        // The hover resets the damage and the defense to the kind's rows
        // (`:27628-27630`), so the base is readable before the charge.
        let base_defense = pr.defense();
        for _ in 0..600 {
            pr.update_rng(&w, &mut player, 1.0 / 60.0, &mut UnifiedRandom::new(0));
        }
        assert_eq!(pr.ai[1], 1.0, "the enraged charge phase armed");
        pr.update_rng(&w, &mut player, 1.0 / 60.0, &mut UnifiedRandom::new(0)); // the charge tick
        let speed = (pr.vx * pr.vx + pr.vy * pr.vy).sqrt();
        assert!(
            (speed - 2.0).abs() < 0.2,
            "the classic charge speed ({speed})"
        );
        // `:27767-27768` — the charge doubles the damage and the defense.
        assert_eq!(
            pr.damage_override,
            Some(NpcKind::SkeletronPrime.contact_damage() * 2),
            "the charge doubles the damage"
        );
        assert_eq!(
            pr.defense_override,
            Some(base_defense * 2),
            "the charge doubles the defense"
        );
        // The 400-tick charge falls back to the hover.
        for _ in 0..400 {
            pr.update_rng(&w, &mut player, 1.0 / 60.0, &mut UnifiedRandom::new(0));
        }
        assert_eq!(pr.ai[1], 0.0, "the hover resumes");
        // `:27862-27863` — the day-time rage is invulnerable.
        w.day_time = true;
        pr.update_rng(&w, &mut player, 1.0 / 60.0, &mut UnifiedRandom::new(0));
        assert_eq!(pr.ai[1], 2.0, "the day-time rage armed");
        assert_eq!(pr.damage_override, Some(9999), "the rage's damage");
        assert_eq!(pr.defense_override, Some(9999), "the rage's defense");
    }

