    #[test]
    fn the_golem_body_charges_slams_and_fires() {
        // `AI_045_Golem` classic core (`NPC.cs:19505-19780`, S1-D-3
        // rewrite): the parts spawn request on the first tick (247 LEFT
        // at -84, 248 RIGHT at +78 — the v1 had them swapped), the
        // num4-ladder charge -> -20 -> the slam at -1, the flight states.
        // WRITTEN NOT RUN (the S1-D-3 round ran code-only).
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        // All parts alive + full hp -> the bare rate 1 (`:19643-19676`);
        // the jungle zone keeps the enrage gate at the solo 1
        // (`:19513-19516` — the player stands below the surface).
        w.golem_head_alive = true;
        w.golem_fist_left_alive = true;
        w.golem_fist_right_alive = true;
        let mut player = crate::player::Player::spawn(&w);
        player.x = 115.0 * 16.0;
        player.y = 90.0 * 16.0;
        player.zones.jungle = true;
        // The body parked ON the floor (the bottom at tile row 120): the
        // gravity pass lands it every tick, so `velocity.Y == 0f` holds
        // at the charge gate (`:19640`).
        let mut body = Npc::new(NpcKind::Golem, 100.0 * 16.0, 120.0 * 16.0 - 140.0, 1, 0.0);
        body.hp = body.max_hp;
        body.caster_counter = 0;
        body.cast_windup = 0;
        // R22 G3: the ctor now carries `SetDefaults`' alpha = 255
        // (`NPC.cs:12175`); this witness pins the CHARGE machine, so the
        // fade is cleared up front (the fade itself has its own witness,
        // `the_golem_family_spawn_fade`).
        body.alpha = 0;
        // The init tick spawn-requests the parts in the C# order.
        body.update_golem(&w, &player);
        assert_eq!(body.wants_sphere.len(), 3, "the parts request");
        assert_eq!(body.wants_sphere[0].0, NpcKind::GolemFistLeft, "247 at -84");
        assert_eq!(body.wants_sphere[1].0, NpcKind::GolemFistRight, "248 at +78");
        assert_eq!(body.wants_sphere[2].0, NpcKind::GolemHead);
        // The charge: the rate-1 ramp hits 300 on tick 300 -> -20.
        for _ in 0..300 {
            body.update_golem(&w, &player);
        }
        assert!(
            body.cast_windup < 0,
            "the charge cap flips ({})",
            body.cast_windup
        );
        // The slam launches on the tick AFTER the one that reaches -1:
        // the `ai[1] += num4` runs first (`:19674`), so the `== -1` arm
        // (`:19681`) fires on the following tick's +1. Detect the launch
        // tick explicitly (the charge-cap flip's exact tick depends on
        // the gravity pass's landing cadence).
        let mut launched = false;
        for _ in 0..25 {
            body.update_golem(&w, &player);
            if body.ai[0] == 1.0 {
                launched = true;
                break;
            }
        }
        assert!(launched, "the slam launched within 25 ticks of the cap");
        assert!(body.vy.abs() > 10.0, "the slam launch");
        assert_eq!(body.local_ai[1], 1.0, "the launch fly-through (`:19684`)");
        // The next tick's release check (`:19627-19637`): the clear line
        // + no solid overlap drops the fly-through flag.
        body.update_golem(&w, &player);
        assert_eq!(body.local_ai[1], 0.0, "the clear-line release");
    }

    #[test]
    fn the_golem_head_fireballs_beams_and_shield() {
        // The head's tether (`:31146-31164`) + the fireball cycle
        // (300, dmg 18/24) + the beam volley (phase-1, two 259 shots).
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        let mut player = crate::player::Player::spawn(&w);
        player.x = 115.0 * 16.0;
        player.y = 100.0 * 16.0;
        player.zones.jungle = true; // the solo balance (the enrage gate off)
        let mut head = Npc::new(
            NpcKind::GolemHead,
            100.0 * 16.0,
            100.0 * 16.0 - 57.0,
            1,
            0.0,
        );
        head.hp = head.max_hp;
        // The phase-0 fireball at 300 (the C# order: the phase write
        // lands AFTER the arms, `:31338-31345`).
        let mut fired = None;
        for _ in 0..301 {
            head.update_golem(&w, &player);
            if let Some(p) = head.wants_hostile_shot.pop() {
                fired = Some(p);
                break;
            }
        }
        let (kind, _, _, fvx, fvy, dmg) = fired.expect("the head fireball");
        assert_eq!(kind, crate::projectile::GOLEM_FIREBALL);
        assert_eq!(dmg, 18, "the phase-0 damage");
        let fsp = (fvx * fvx + fvy * fvy).sqrt();
        assert!((fsp - 8.0).abs() < 0.01, "the 8-speed fireball (`:31193`)");
        // The phase-1 (half life): the 24-damage fireball + the beams.
        // The player parks IN-BAND (inside `Center.X +- width`) so the
        // volley takes the two-shot arm (`:31281-31307`); the restored
        // `60 + Next(600)` trigger draws from the scratch stream — the
        // first volley lands inside the 660-tick worst case.
        player.x = 100.0 * 16.0;
        head.hp = head.max_hp / 3;
        head.ai[1] = 0.0;
        let mut beam = 0;
        for _ in 0..700 {
            head.update_golem(&w, &player);
            while let Some(p) = head.wants_hostile_shot.pop() {
                if p.0 == crate::projectile::GOLEM_EYE_BEAM && p.5 == 28 {
                    beam += 1;
                }
            }
        }
        assert!(beam >= 2, "the two-shot beam volley ({beam})");
    }

    #[test]
    fn the_golem_head_turn_rows_and_free_head_mouth_row() {
        // W4-c5 — `FindFrame` cases 246/249 (`NPC.cs:72931-72981`): the
        // attached head's mouth row reads the STORED `localAI[0]` flag
        // the aiStyle-46 machine writes (`:72934`/`:72945`), NOT a
        // recomputed ai[1] window (the case-249 R23 G5 precedent); the
        // phase-1 rows add the three-way `localAI[1]` turn (+4 left /
        // +2 right / 0 in-band, mirrored to `head_turn`); the free head
        // carries the mouth row alone.
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        let mut player = crate::player::Player::spawn(&w);
        // In-band (|pcx - cx| <= 70) and below the surface line: the
        // jungle zone keeps the solo balance calm (num675 = 1,
        // num688 = 1 — at hp max/3 the 0.4 tier doubles the add to 2).
        player.x = 100.0 * 16.0 - 10.0;
        player.y = 100.0 * 16.0;
        player.zones.jungle = true;
        let mut head = Npc::new(
            NpcKind::GolemHead,
            100.0 * 16.0 - 3.0 - 35.0,
            100.0 * 16.0 - 57.0 - 35.0,
            -1,
            0.0,
        );
        head.hp = head.max_hp / 3;
        head.ai[0] = 1.0;
        // The in-band player: the turn is 0; ai[1] = 5 -> 7 (the 0.4
        // tier's double add) < 20 opens the mouth (`:31238`) -> row 1
        // without the turn offset.
        head.ai[1] = 5.0;
        head.update_golem(&w, &player);
        head.find_frame();
        assert_eq!(head.local_ai[0], 1.0, "the AI's open-mouth write");
        assert_eq!(head.head_turn, 0, "the in-band turn");
        assert_eq!(head.frame, 1, "the mouth row without the turn offset");
        // The player to the left: -1 -> +4; mid-cadence -> the closed
        // mouth (row 0 + 4). W4-c5: ai[1] is preset BEFORE the tick — the
        // row reads the flag the AI writes on the post-add counter.
        player.x = (100.0 * 16.0 - 200.0) as f32;
        head.ai[1] = 150.0;
        head.update_golem(&w, &player);
        head.find_frame();
        assert_eq!(head.head_turn, -1, "the left turn");
        assert_eq!(head.local_ai[1], -1.0, "the C# slot the turn mirrors");
        assert_eq!(head.frame, 4, "the +4 row");
        // The player to the right: +1 -> +2 with the mouth open.
        player.x = (100.0 * 16.0 + 200.0) as f32;
        head.ai[1] = 295.0;
        head.update_golem(&w, &player);
        head.find_frame();
        assert_eq!(head.head_turn, 1, "the right turn");
        assert_eq!(head.local_ai[0], 1.0, "the AI wrote the mouth flag");
        assert_eq!(head.frame, 3, "the mouth +2 row");
        // The free head: case 249's mouth-only rows, no turn — R23 G5:
        // the row reads the STORED `localAI[0]` flag (`NPC.cs:72963`),
        // not a recomputed ai[1] window.
        let mut free = Npc::new(NpcKind::GolemHeadFree, 100.0 * 16.0, 100.0 * 16.0, -1, 0.0);
        free.hp = free.max_hp;
        free.local_ai[0] = 1.0;
        free.find_frame();
        assert_eq!(free.frame, 1, "the free head's mouth row");
        free.local_ai[0] = 0.0;
        free.find_frame();
        assert_eq!(free.frame, 0, "the free head's closed row");
    }

    /// W4-c5 witness 1 — `FindFrame` case 246 reads the STORED
    /// `localAI[0]` mouth flag (`NPC.cs:72934`/`:72945`), NOT a recomputed
    /// `ai[1]` window (the case-249 R23 G5 precedent): the flag can
    /// diverge from the counter, and the row follows the FLAG.
    #[test]
    fn w4_c5_the_head_mouth_row_reads_the_stored_local_ai0_flag() {
        let mut head = Npc::new(NpcKind::GolemHead, 1600.0, 1543.0, -1, 0.0);
        head.hp = head.max_hp;
        // Phase 0: the counter is mid-cadence (the old window read would
        // pick row 0) but the flag rides OPEN — the C# picks row 1.
        head.ai[0] = 0.0;
        head.ai[1] = 150.0;
        head.local_ai[0] = 1.0;
        head.find_frame();
        assert_eq!(head.frame, 1, "the flag wins over the window (phase 0)");
        // And the mirror: a window-open counter with the flag CLOSED
        // picks row 0 — the read is the flag alone.
        head.ai[1] = 5.0;
        head.local_ai[0] = 0.0;
        head.find_frame();
        assert_eq!(head.frame, 0, "the closed flag holds row 0");
        // Phase 1: the same flag read, then the turn adds ride on top
        // (`:72943-72960`). The flag open + a left turn -> 1 + 4.
        head.ai[0] = 1.0;
        head.ai[1] = 150.0;
        head.local_ai[0] = 1.0;
        head.head_turn = -1;
        head.find_frame();
        assert_eq!(head.frame, 5, "the phase-1 mouth + left turn");
        head.head_turn = 1;
        head.find_frame();
        assert_eq!(head.frame, 3, "the phase-1 mouth + right turn");
    }

    /// W4-c5 witness 2 — the AI→frame seam end to end: `golem_head_step`
    /// writes `localAI[0]` on the 300-cadence window (`NPC.cs:31181`/
    /// `:31186` phase 0, `:31238`/`:31242` phase 1) and `find_frame` reads
    /// it back — the fire tick's counter reset leaves the flag OPEN (the
    /// divergence the window recompute could never show).
    #[test]
    fn w4_c5_the_ai_written_mouth_flag_drives_the_head_frame() {
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        let mut player = crate::player::Player::spawn(&w);
        player.zones.jungle = true; // solo balance: the enrage gate off
        let mut head = Npc::new(
            NpcKind::GolemHead,
            100.0 * 16.0 - 3.0 - 35.0,
            100.0 * 16.0 - 57.0 - 35.0,
            -1,
            0.0,
        );
        head.hp = head.max_hp;
        head.alpha = 0;
        // Phase 0, the last-20 window: 299 -> 300 fires, the reset leaves
        // ai[1] = 0 with the flag OPEN (`:31181` wrote it pre-fire).
        head.ai[1] = 299.0;
        head.update_golem(&w, &player);
        assert_eq!(head.ai[1], 0.0, "the fire tick's reset");
        assert_eq!(head.local_ai[0], 1.0, "the window write survives it");
        head.find_frame();
        assert_eq!(head.frame, 1, "the stored flag drives the row");
        // Mid-cadence: the flag closes and the row follows.
        head.ai[1] = 150.0;
        head.update_golem(&w, &player);
        assert_eq!(head.local_ai[0], 0.0);
        head.find_frame();
        assert_eq!(head.frame, 0);
        // Phase 1: the same seam on the num688 ladder (solo balance 1 ->
        // 1/tick at full hp); 295 -> 296 opens the mouth, no fire.
        head.hp = head.max_hp / 3;
        head.ai[0] = 1.0;
        head.ai[1] = 295.0;
        head.update_golem(&w, &player);
        assert_eq!(head.local_ai[0], 1.0, "the phase-1 window write");
        head.find_frame();
        assert_eq!(head.frame, 1, "in-band: no turn offset");
    }

    #[test]
    fn w1_2_the_free_head_toggles_tile_collide_on_the_blocked_line() {
        // W1-2 (`NPC.cs:31363-31371`): the free head starts tile-colliding
        // (`SetDefaults` 249 `:12207-12220` has no noTileCollide); a
        // BLOCKED line to the player sets the flag (local_ai[1]) AND
        // flag53 (the ai[1] pin at 20); a CLEAR line while the flag rides
        // AND a solid overlap releases it. WRITTEN NOT RUN (code-only).
        // Layout: ground_air's cave is rows 125-134, cols 60-139; the
        // head hovers INSIDE the cave (air), the player below it in the
        // same cave; a temporary solid plug rows 129-130 blocks the line.
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        let mut player = crate::player::Player::spawn(&w);
        player.zones.jungle = true;
        player.x = 100.0 * 16.0;
        player.y = 130.0 * 16.0; // centre tile (100, 131), cave air
        for x in 95..106 {
            for y in 129..131 {
                let i = w.index(x, y);
                w.tiles[i] = Tile {
                    kind: 1,
                    ..Default::default()
                };
                w.tiles[i].flags |= FLAG_ACTIVE;
            }
        }
        // The head in the cave air above the plug (box rows 126-130).
        let mut free =
            Npc::new(NpcKind::GolemHeadFree, 100.0 * 16.0, 126.0 * 16.0, -1, 0.0);
        free.hp = free.max_hp;
        assert_eq!(free.local_ai[1], 0.0, "249 starts tile-colliding");
        free.update_golem(&w, &player);
        assert_eq!(free.local_ai[1], 1.0, "the blocked line sets the flag");
        assert_eq!(free.ai[1], 20.0, "flag53 pins the cadence at 20");
        // Carve the plug away: the line clears, but the head is in AIR —
        // the `SolidTiles` half fails, the flag keeps riding.
        for x in 95..106 {
            for y in 129..131 {
                let i = w.index(x, y);
                w.tiles[i] = Tile::default();
            }
        }
        free.update_golem(&w, &player);
        assert_eq!(free.local_ai[1], 1.0, "clear line + no solids: keeps flying");
        // Drop the head so its bottom edge overlaps the cave floor (row
        // 135) while its centre line to the player stays cave air: the
        // clear line + the solid overlap releases the flag.
        free.x = 100.0 * 16.0;
        free.y = 131.0 * 16.0; // box rows 131-135.4, floor at row 135
        free.vx = 0.0;
        free.vy = 0.0;
        free.update_golem(&w, &player);
        assert_eq!(free.local_ai[1], 0.0, "clear line + solids: released");
        // R23 G5: the flag53-pinned tick above stored the PRE-pin mouth
        // flag; FindFrame reads the STORED flag, not the pinned cadence.
        // Re-block the line with the cadence in the mouth window (285):
        // the flag stores 1, the pin lands 20 — the row stays OPEN.
        for x in 95..106 {
            for y in 129..131 {
                let i = w.index(x, y);
                w.tiles[i] = Tile {
                    kind: 1,
                    ..Default::default()
                };
                w.tiles[i].flags |= FLAG_ACTIVE;
            }
        }
        free.x = 100.0 * 16.0;
        free.y = 126.0 * 16.0;
        free.vx = 0.0;
        free.vy = 0.0;
        free.ai[1] = 285.0;
        free.update_golem(&w, &player);
        assert_eq!(free.ai[1], 20.0, "flag53 pins the cadence");
        assert_eq!(free.local_ai[0], 1.0, "the PRE-pin window stored 1");
        free.find_frame();
        assert_eq!(free.frame, 1, "the pinned tick keeps the mouth OPEN (R23 G5)");
        // With the flag down the tail tile-collides. The re-block leg above
        // RE-SET the fly flag (the line is blocked again), so the impact leg
        // must clear the plug AND drop the head onto the floor first: the
        // clear line + the solid overlap releases the flag at the arm top,
        // and the SAME tick's tail runs the collision pass. The hover aim is
        // UP (the player sits above the head's centre - 300): vy steps
        // to -0.05, and the box already overlaps the solid floor — the
        // y-pass zeroes vy and latches collide_y instead of integrating
        // (the C#'s TileCollision stand-in). The old unconditional raw
        // tail moved y by -0.05 with collide_y false.
        for x in 95..106 {
            for y in 129..131 {
                let i = w.index(x, y);
                w.tiles[i] = Tile::default();
            }
        }
        free.x = 100.0 * 16.0;
        free.y = 131.0 * 16.0; // box rows 131-135.4, floor at row 135
        free.vx = 0.0;
        free.vy = 0.0;
        let y_before = free.y;
        free.update_golem(&w, &player);
        assert_eq!(free.local_ai[1], 0.0, "clear line + solids: released");
        assert_eq!(free.vy, 0.0, "the impact zeroed vy");
        assert!(free.collide_y, "the impact latched collideY");
        assert_eq!(free.y, y_before, "no integration into the floor");
    }

    #[test]
    fn r22_g2_the_golem_body_refaces_every_flight_tick() {
        // R22 G2 (`NPC.cs:19723`, `:19767-19770`): the C# re-runs
        // `TargetClosest` at the flight tick AND at the invalid-target
        // tail (the `target <= 0` gate INCLUDES solo 0 — every tick);
        // `SetTargetTrackingValues` (`:77744-77755`) re-faces from the
        // int-centre compare. The v1 wrote facing ad hoc at the slam and
        // strafed the stale way while the player crossed the body.
        // WRITTEN NOT RUN (code-only).
        let mut w = ground_air();
        w.golem_present = true;
        let mut player = crate::player::Player::spawn(&w);
        player.zones.jungle = true; // the solo balance below the surface
        player.x = 115.0 * 16.0;
        player.y = 90.0 * 16.0;
        let mut body = Npc::new(NpcKind::Golem, 100.0 * 16.0, 100.0 * 16.0, 1, 0.0);
        body.hp = body.max_hp;
        body.alpha = 0;
        body.caster_counter = 1; // skip the parts-spawn tick
        body.ai[0] = 1.0; // the flight state
        body.vy = -5.0; // airborne: the flight arm, not the landing
        body.facing = 1; // STALE: aimed right from the slam
        body.sprite_dir = 1;
        // The player now LEFT of the body: the flight tick's retarget
        // flips the facing and the strafe accelerates LEFT (-0.2).
        player.x = 80.0 * 16.0;
        body.update_golem(&w, &player);
        assert_eq!(body.facing, -1, "the flight tick re-faces (`:19723`)");
        assert_eq!(body.sprite_dir, -1);
        assert_eq!(body.target, 0, "the scan commits the solo slot");
        assert_eq!(
            body.target_rect,
            (player.x as i32, player.y as i32, 20, 42),
            "the tracking rect rides the session player"
        );
        // vx started 0, the strafe added -0.2 (the fresh direction).
        assert!(body.vx < 0.0, "the strafe reads the fresh facing");
        // The grounded charge tick (no slam) still re-faces via the tail
        // gate (`:19767-19770` — `target <= 0` includes solo 0).
        body.ai[0] = 0.0;
        body.vy = 0.0;
        body.vx = 0.0;
        body.facing = -1; // stale: aimed left
        player.x = 115.0 * 16.0; // the player crosses back to the RIGHT
        body.update_golem(&w, &player);
        assert_eq!(body.facing, 1, "the tail gate re-faces every tick");
        // The Manhattan-3000 despawn re-check (`:19771-19779`): the
        // retarget runs, the distance still exceeds -> despawn window 0.
        player.x = 400.0 * 16.0;
        body.update_golem(&w, &player);
        assert_eq!(body.despawn_timer, 0, "the re-checked despawn");
        assert_eq!(body.facing, 1, "the despawn retarget still faces");
    }

    #[test]
    fn r23_g3_the_free_head_faces_the_target_not_the_velocity() {
        // R23 G3 (`NPC.cs:31377`, `:77744-77755`): the C# arm writes NO
        // direction — the facing rides `TargetClosest`'s target-face.
        // The old tail wrote facing from the velocity sign, so a head
        // drifting AWAY from the player faced backwards. WRITTEN NOT RUN.
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        w.golem_hp = 15000;
        w.golem_max_hp = 15000;
        let mut player = crate::player::Player::spawn(&w);
        player.zones.jungle = true;
        player.x = 80.0 * 16.0; // LEFT of the head
        player.y = 130.0 * 16.0;
        let mut free = Npc::new(NpcKind::GolemHeadFree, 100.0 * 16.0, 126.0 * 16.0, 1, 0.0);
        free.hp = free.max_hp;
        free.vx = 2.0; // drifting RIGHT, away from the player
        free.facing = 1;
        free.update_golem(&w, &player);
        assert_eq!(free.facing, -1, "the target-face wins over the vx sign");
        assert_eq!(free.sprite_dir, -1);
        assert_eq!(free.target, 0);
        // The reverse drift: the player RIGHT, the head drifting LEFT —
        // the old vx-sign stand-in faced -1, the target-face flips +1.
        player.x = 120.0 * 16.0;
        free.vx = -2.0;
        free.update_golem(&w, &player);
        assert_eq!(free.facing, 1, "the target-face tracks the crossing");
    }

    #[test]
    fn r22_g3_the_golem_body_spawns_at_alpha_255() {
        // R22 G3 (`NPC.cs:12175`): `SetDefaults` 245 sets `alpha = 255` —
        // the ctor carries it (the altar summon and the debug spawn both
        // construct directly), so the body fades in over 26 ticks
        // (`:19535-19543`) from ANY spawn site, not just the resolver.
        let body = Npc::new(NpcKind::Golem, 0.0, 0.0, 1, 0.0);
        assert_eq!(body.alpha, 255, "the body's SetDefaults alpha");
        // The free head 249 has NO alpha row (`:12207-12220`) — stays 0.
        let free = Npc::new(NpcKind::GolemHeadFree, 0.0, 0.0, 1, 0.0);
        assert_eq!(free.alpha, 0, "249 writes no alpha");
    }
    #[test]
    fn the_golem_family_spawn_fade() {
        // `SetDefaults`' `alpha = 255` (`NPC.cs:12176/12190/12201`) with
        // the machines' `alpha -= 10` fades (`:19535-19543`,
        // `:19248-19255`, `:31169-31173`): the family spawns invisible and
        // takes 26 ticks to fade in; the draw's tint maps it through
        // `GetAlpha`'s `(255 - alpha)/255`.
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        let mut player = crate::player::Player::spawn(&w);
        let mut fist = Npc::new(NpcKind::GolemFistLeft, 100.0 * 16.0, 100.0 * 16.0, -1, 0.0);
        fist.alpha = 255;
        fist.hp = fist.max_hp;
        for t in 1..=26u16 {
            // S1-D-3: the fists ride the aiStyle-47 axis arm now.
            crate::npc_ai_style47::ai_047_golem_fist(&mut fist, &w, &player);
            let want = 255u8.saturating_sub((t * 10).min(255) as u8);
            assert_eq!(fist.alpha, want, "the fade at tick {t}");
        }
        assert_eq!(fist.alpha, 0, "the fade completes at 26 ticks");
        // The body's fade resets the charge ramp each tick (`ai[1] = 0`,
        // `:19535-19543`) — the grounded arm's `+= 1` then leaves it at
        // 1: the ramp never advances while the fade runs.
        let mut body = Npc::new(NpcKind::Golem, 100.0 * 16.0, 120.0 * 16.0 - 140.0, -1, 0.0);
        body.alpha = 255;
        body.hp = body.max_hp;
        body.update_golem(&w, &player);
        assert_eq!(body.alpha, 245, "the body's fade");
        assert_eq!(body.cast_windup, 1, "the ramp holds at the reset");
    }
    #[test]
    fn the_golem_fist_side_gate_and_damage_tiers() {
        // `AI_047_GolemFist`'s two gates: the side gate (`:19308-19317`)
        // and the damaged tiers (`:19291-19304` / `:19361-19378`).
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        let mut player = crate::player::Player::spawn(&w);
        player.zones.jungle = true; // the solo balance keeps the v1 numbers
        // The player stands RIGHT of the left fist's `Center + 100`:
        // the gate fails, the cadence resets and the fist never dashes.
        player.x = 130.0 * 16.0;
        player.y = 100.0 * 16.0;
        let mut fist = Npc::new(NpcKind::GolemFistLeft, 1490.0, 100.0 * 16.0, 1, 0.0);
        fist.hp = fist.max_hp;
        for _ in 0..400 {
            crate::npc_ai_style47::ai_047_golem_fist(&mut fist, &w, &player);
        }
        assert_eq!(fist.ai[0], 0.0, "the blocked gate keeps the follow state");
        // The same scene with the damaged body: the cadence runs 11x
        // (`:19301`'s +10 body tier on the +1) and the dash launches at
        // 22 (12 + 10).
        w.golem_hp_ratio = 0.5;
        player.x = 60.0 * 16.0;
        let mut fist2 = Npc::new(NpcKind::GolemFistLeft, 1490.0, 100.0 * 16.0, 1, 0.0);
        fist2.hp = fist2.max_hp;
        let mut transition_tick = None;
        for t in 0..45 {
            crate::npc_ai_style47::ai_047_golem_fist(&mut fist2, &w, &player);
            if fist2.ai[0] == 1.0 && transition_tick.is_none() {
                transition_tick = Some(t);
            }
        }
        assert_eq!(fist2.ai[0], 2.0, "the dash state after the wind-up");
        let dash_speed = (fist2.vx * fist2.vx + fist2.vy * fist2.vy).sqrt();
        assert!(
            (dash_speed - 22.0).abs() < 2.0,
            "the 12+10 damaged lunge ({dash_speed})"
        );
        // The 11x cadence fires the 60-contact inside 6 ticks (60/11).
        assert!(
            transition_tick.expect("the transition fires") < 10,
            "the 11x cadence is fast"
        );
    }

    #[test]
    fn the_golem_fists_follow_wind_up_and_dash() {
        // `AI_047_GolemFist` (`NPC.cs:19231-19503`): the follow to the
        // anchor, the 60-contact -> the 30 wind-up, the dash. The player
        // stands LEFT of the left fist's anchor — the side gate
        // (`:19308-19317`) only then lets the 60-cadence transition.
        let mut w = ground_air();
        w.golem_present = true;
        w.golem_x = 100.0 * 16.0;
        w.golem_y = 100.0 * 16.0;
        let mut player = crate::player::Player::spawn(&w);
        player.zones.jungle = true; // the solo balance keeps the 12-speed lunge
        player.x = 60.0 * 16.0;
        player.y = 100.0 * 16.0;
        // The fist starts just left of its anchor column (the anchor's
        // center is 1516): the first tick closes the last px and the
        // in-contact cadence starts.
        let mut fist = Npc::new(NpcKind::GolemFistLeft, 1490.0, 100.0 * 16.0, 1, 0.0);
        fist.hp = fist.max_hp;
        // The follow: the fist closes the last few px to the anchor.
        crate::npc_ai_style47::ai_047_golem_fist(&mut fist, &w, &player);
        assert!(fist.vx > 0.0, "the follow pulls toward the anchor");
        // The contact (60) -> the wind-up (30): the dash state opens on
        // the 92nd tick with the 12-speed lunge; the >700 anchor
        // distance ends the dash (`:19445`) — the assertion lands inside
        // the dash window.
        for _ in 0..91 {
            crate::npc_ai_style47::ai_047_golem_fist(&mut fist, &w, &player);
        }
        assert_eq!(fist.ai[0], 2.0, "the dash state after the wind-up");
        let dash_speed = (fist.vx * fist.vx + fist.vy * fist.vy).sqrt();
        assert!(
            (dash_speed - 12.0).abs() < 2.0,
            "the 12-speed lunge ({dash_speed})"
        );
    }

    /// `FindFrame`'s `case 376` (`NPC.cs:71007-71018`): the Sleeping Angler's
    /// two rows flip once past 30 ticks and wrap — the headless twin of the
    /// screenshot pair (the port's draw rides the same rows).

    #[test]
    fn the_dye_trader_and_party_girl_kinds_stats_roundtrip_and_shops() {
        // `SetDefaults` 207 (`NPC.cs:11654`) and 208 (`:11668`): the town
        // twin's numbers, the kind<->u16 round-trips, the shop indexes
        // (`NPCInteractions.cs:499-500`'s `Shop(207, 12)`/`Shop(208, 13)`) and
        // the bestiary rows.
        for (kind, id) in [(NpcKind::DyeTrader, 207u16), (NpcKind::PartyGirl, 208)] {
            assert_eq!(kind.max_hp(), 250, "{kind:?}");
            assert_eq!(kind.contact_damage(), 10, "{kind:?}");
            assert_eq!(kind.cs_id(), id, "{kind:?}");
            assert_eq!(kind.size(), (18.0, 40.0), "{kind:?}");
            assert!(kind.is_town_resident(), "{kind:?}");
        }
        assert_eq!(NpcKind::DyeTrader.to_u16(), 167);
        assert_eq!(NpcKind::from_u16(167), Some(NpcKind::DyeTrader));
        assert_eq!(NpcKind::PartyGirl.to_u16(), 168);
        assert_eq!(NpcKind::from_u16(168), Some(NpcKind::PartyGirl));
        assert_eq!(
            crate::world_sim::npcs::shop_index_for_kind(NpcKind::DyeTrader),
            Some(12)
        );
        assert_eq!(
            crate::world_sim::npcs::shop_index_for_kind(NpcKind::PartyGirl),
            Some(13)
        );
        assert_eq!(
            crate::bestiary::entry_for_npc(NpcKind::DyeTrader, SlimeVariant::Blue).net_id,
            207
        );
        assert_eq!(
            crate::bestiary::entry_for_npc(NpcKind::PartyGirl, SlimeVariant::Blue).net_id,
            208
        );
    }

