        assert_eq!(k.ai[3], k.max_hp as f32, "the hp latch (:43134-43137)");
        assert_eq!(k.king_slime_local[3], 1.0, "the one-shot init");
        assert_eq!(k.ai[0], -98.0, "-100 init + the full-life +2 beat");
